  "max-deliveries": option("max-deliveries", "positive-integer", "Set how many deliveries may use the standing approval.", "Imposta quante consegne possono usare l’approvazione permanente."),
  "standing-expires-at": option("expires-at", "ISO-8601", "Set when the standing approval stops covering work; required and capped by the project maximum.", "Imposta quando l’approvazione permanente smette di coprire il lavoro; obbligatorio e limitato dal massimo del progetto."),
  "budget-per-delivery": option("budget-per-delivery", "amount", "Limit the metered cost of each delivery (a decimal amount). Accepted only when a meter that reports delivery cost is configured; a step whose cost is not measured falls back to a normal confirmation.", "Limita il costo misurato di ogni consegna (importo decimale). Accettato solo se è configurato un contatore che riporta il costo delle consegne; un passo con costo non misurato torna alla conferma normale."),
  "budget-total": option("budget-total", "amount", "Limit the metered cost of all deliveries that use the standing approval together (a decimal amount). Accepted only when a meter that reports delivery cost is configured.", "Limita il costo misurato di tutte le consegne che usano l’approvazione permanente insieme (importo decimale). Accettato solo se è configurato un contatore che riporta il costo delle consegne."),
  "code-review": option("code-review", "required|not-required", "Record the user's answer: does this pull request need a code review before the plugin merges it? Required for new pull-request deliveries; never inferred from earlier stories.", "Registra la risposta dell’utente: questa pull request richiede una revisione del codice prima del merge eseguito dal plugin? Obbligatoria per le nuove consegne pull request; mai dedotta da storie precedenti.", { values: ["not-required", "required"] }),
  "code-review-actor-type": option("code-review-actor-type", "human", "Record that a person made the code review choice; an agent or system cannot.", "Registra che la scelta sulla revisione del codice è di una persona; un agente o un sistema non può farla.", { values: ["human"] }),
  "code-review-approval-source": option("code-review-approval-source", "explicit-user", "Record that the code review choice is the user's explicit answer.", "Registra che la scelta sulla revisione del codice è la risposta esplicita dell’utente.", { values: ["explicit-user"] }),
  "code-review-summary": option("code-review-summary", "text", "Quote the user's answer to the code review question.", "Riporta la risposta dell’utente alla domanda sulla revisione del codice."),
  "code-review-actor": option("code-review-actor", "person-id", "Name the person who answered the code review question.", "Indica la persona che ha risposto alla domanda sulla revisione del codice."),
  "merge": option("merge", "manual|after-confirmation|automatic", "Record the user's answer on how this pull request is merged: manual (the user merges it on GitHub, then the delivery is reconciled), after-confirmation (the plugin merges after a confirmation), or automatic (the plugin merges without a merge confirmation once every other gate passes; needs --merge-allowed and a level above supervised). Without it the merge waits for confirmation.", "Registra la risposta dell’utente su come fare il merge di questa pull request: manual (l’utente fa il merge su GitHub, poi la consegna viene riconciliata), after-confirmation (il plugin fa il merge dopo una conferma) o automatic (il plugin fa il merge senza conferma quando tutti gli altri controlli passano; richiede --merge-allowed e un livello superiore a supervised). Senza questa opzione il merge attende la conferma.", { values: ["after-confirmation", "automatic", "manual"] }),
  "merge-actor-type": option("merge-actor-type", "human", "Record that a person made the merge choice; an agent or system cannot.", "Registra che la scelta sul merge è di una persona; un agente o un sistema non può farla.", { values: ["human"] }),
  "merge-approval-source": option("merge-approval-source", "explicit-user", "Record that the merge choice is the user's explicit answer.", "Registra che la scelta sul merge è la risposta esplicita dell’utente.", { values: ["explicit-user"] }),
  "merge-summary": option("merge-summary", "text", "Quote the user's answer to the merge question.", "Riporta la risposta dell’utente alla domanda sul merge."),
  "merge-actor": option("merge-actor", "person-id", "Name the person who answered the merge question.", "Indica la persona che ha risposto alla domanda sul merge."),
  "standing-code-review": option("code-review", "required|not-required", "Record the user's code review choice for every pull request the standing approval covers.", "Registra la scelta dell’utente sulla revisione del codice per ogni pull request coperta dall’approvazione permanente.", { values: ["not-required", "required"] }),
  "merge-allowed": option("merge-allowed", null, "Include pull-request merge in the exact allowed action boundary.", "Include il merge della pull request nel limite esatto delle azioni consentite.", { boolean: true }),
