  "output-decision-id": option("decision-id", "id", "Use the exact approved decision for an intentional duplicate or structure override. A new id records the exception in the same output link call, together with --rationale (or --approval-evidence), --actor-type human and --approval-source.", "Usa la decisione approvata ed esatta per un duplicato intenzionale o una modifica della struttura. Un nuovo id registra l’eccezione nella stessa chiamata output link, insieme a --rationale (o --approval-evidence), --actor-type human e --approval-source."),
  "verification-receipt-file": option("receipt-file", "path", "Read the generator or verification receipt for this exact artifact.", "Legge la ricevuta di generazione o verifica di questo artefatto esatto."),
  "output-supersedes": option("supersedes", "link-id", "Replace an earlier output link of the same story and type (for example one linked by a cancelled delivery). The earlier link stays in history, marked superseded, and no longer counts. Requires --rationale and --actor-type human.", "Sostituisce un collegamento di output precedente della stessa story e dello stesso tipo (per esempio quello di una consegna annullata). Il collegamento precedente resta nello storico, marcato come sostituito, e non conta più. Richiede --rationale e --actor-type human."),
  rationale: option("rationale", "text", "Explain an explicitly approved output-link exception.", "Spiega un’eccezione al collegamento dell’output approvata esplicitamente."),
  "output-mode": option("mode", "reuse|delta|new", "Choose whether this artifact reuses, extends, or newly creates the required output.", "Sceglie se l’artefatto riusa, estende oppure crea un nuovo output richiesto.", { values: ["delta", "new", "reuse"] }),
