  "abandon-replaced-by": option("replaced-by", "story-id", "Name the story that continues the abandoned work.", "Indica la story che prosegue il lavoro abbandonato."),
  "closure-reason": option("reason", "text", "Explain why the work will not be delivered by the closed stories.", "Spiega perché il lavoro non sarà consegnato dalle story chiuse."),
  "allow-non-base-branch": option("allow-non-base-branch", null, "Refresh from a checkout that is not the base branch; only when that checkout really is the project state to record.", "Aggiorna da un checkout che non è il branch base; solo quando quel checkout è davvero lo stato del progetto da registrare.", { boolean: true }),
  "allow-uncommitted-changes": option("allow-uncommitted-changes", null, "Record files of the baseline scope that have changes not yet committed, for a person's review.", "Registra i file dell’ambito del baseline con modifiche non ancora salvate in un commit, per la revisione di una persona.", { boolean: true }),
  "refresh-withdrawal-from": option("from", "baseline-id", "Name the baseline the withdrawn refresh replaces; needed only when the proposed baseline is not on this computer.", "Indica il baseline che l’aggiornamento ritirato sostituisce; serve solo quando il baseline proposto non è su questo computer."),
