  "allow-rebase-committed": option("allow-rebase-committed", null, "Let story sync rebase commits that already carry a git.commit receipt and are not pushed yet; the rebase changes their SHA, so the receipt stops matching and the governed commit has to be made again.", "Permette a story sync di fare il rebase di commit che hanno già una ricevuta git.commit e non sono ancora pubblicati; il rebase ne cambia lo SHA, quindi la ricevuta non corrisponde più e il commit governato va rifatto.", { boolean: true }),
  "to-base": option("to-base", null, "Push the records commit straight onto the remote base branch (rebuilt once if another computer pushed first) instead of its own branch.", "Invia il commit dei record direttamente sul branch base del remote (ricostruito una volta se un altro computer ha inviato prima) invece che su un branch a sé.", { boolean: true }),
