  "message-flush": option("flush", null, "Send the queued messages now, ignoring the retry schedule.", "Invia subito i messaggi in coda, ignorando la pianificazione dei tentativi.", { boolean: true }),
  "message-drop": option("drop", "outbox-id", "Discard one queued message (the id shown by message outbox) without sending it.", "Scarta un messaggio in coda (l’id mostrato da message outbox) senza inviarlo."),
